/**
 * Short sound effects, generated by `scripts/gen-sounds.ts`. Played only when the learner has
 * sounds on; never throws, so a device without audio output cannot break a lesson.
 */
import { createAudioPlayer, type AudioPlayer } from 'expo-audio';

import { useSettings } from '@/features/settings/store';

const SOURCES = {
  correct: require('../../../assets/sounds/correct.wav') as number,
  wrong: require('../../../assets/sounds/wrong.wav') as number,
  complete: require('../../../assets/sounds/complete.wav') as number,
  achievement: require('../../../assets/sounds/achievement.wav') as number,
};

export type SoundName = keyof typeof SOURCES;

const players = new Map<SoundName, AudioPlayer>();

function playerFor(name: SoundName): AudioPlayer {
  let p = players.get(name);
  if (!p) {
    p = createAudioPlayer(SOURCES[name]);
    players.set(name, p);
  }
  return p;
}

export function playSound(name: SoundName) {
  if (!useSettings.getState().sounds) return;
  try {
    const p = playerFor(name);
    void p.seekTo(0);
    p.play();
  } catch {
    // No audio output: effects are optional.
  }
}
